import sys

def solve():
    tokens = sys.stdin.read().split()
    n = int(tokens[0])
    cows = []
    idx = 1
    for _ in range(n):
        d = tokens[idx]
        p = int(tokens[idx + 1])
        idx += 2
        cows.append((d, p))
    ans = n
    for _, x in cows:
        liars = 0
        for d, p in cows:
            if (d == 'L' and x > p) or (d == 'G' and x < p):
                liars += 1
        if liars < ans:
            ans = liars
    print(ans)

if __name__ == "__main__":
    solve()

