#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<char, int>> cows(n);
    for (int i = 0; i < n; i++) cin >> cows[i].first >> cows[i].second;
    int ans = n;
    for (int i = 0; i < n; i++) {
        int x = cows[i].second;
        int liars = 0;
        for (int j = 0; j < n; j++) {
            if ((cows[j].first == 'L' && x > cows[j].second) ||
                (cows[j].first == 'G' && x < cows[j].second)) {
                liars++;
            }
        }
        ans = min(ans, liars);
    }
    cout << ans << '\n';
    return 0;
}

